from .loader import Loader
from ..base import BaseAnalysis

NO_VALUE = -1.0


class WcdmaTraceAnalyzer(object):

    def __init__(self, file_path):
        self.file_path = file_path
        self.container = Loader().read_from_file(self.file_path)

    def get_average_uplink_throughput(self):
        return ThroughputAnalysis(self.container).get_average_in_uplink()


class ThroughputAnalysis(BaseAnalysis):
    def __init__(self, container):
        super(ThroughputAnalysis, self).__init__()
        self.container = container

    def get_average_in_uplink(self):
        # type: () -> float
        """
        Throughput value is the last value in each line of trace TXT file, as in

        7695,2,16,17,789,35,58,554,40,0,4,2128,6816293,104,1,1,4294032;

        The raw average value is divided by 1000 to return the average throughput in kbps.
        """

        if not self.container.traces:
            return NO_VALUE

        tputs = [line[-1] for line in self.container.traces]
        return self.calculate_rounded_average(tputs, precision=2) / 1000.0
